<?php declare(strict_types=1);namespace App\Infrastructure\Persistence\Doctrine\Arena;use App\Domain\Arena\Repository\DuelRoundCloserInterface;use App\Domain\Arena\Service\DuelScoring;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelAnswerRecord;use App\Infrastructure\Persistence\Doctrine\Arena\Entity\DuelPlayerRecord;use Doctrine\ORM\EntityManagerInterface;final class DoctrineDuelRoundCloser implements DuelRoundCloserInterface{public function __construct(private readonly EntityManagerInterface $em,private readonly DuelScoring $scoring=new DuelScoring()){}public function closeIfReady(string $duelId,int $position,\DateTimeImmutable $deadline):bool{$answers=$this->em->getRepository(DuelAnswerRecord::class)->findBy(['duelId'=>$duelId,'position'=>$position],['receivedAt'=>'ASC','id'=>'ASC']);$players=(int)$this->em->createQueryBuilder()->select('COUNT(p.userId)')->from(DuelPlayerRecord::class,'p')->where('p.duelId=:d')->setParameter('d',$duelId)->getQuery()->getSingleScalarResult();if(count($answers)<$players&&new \DateTimeImmutable('now',new \DateTimeZone('UTC'))<$deadline)return false;$scores=$this->scoring->score(array_map(static fn(DuelAnswerRecord $a):array=>['userId'=>$a->userId,'correct'=>(bool)$a->isCorrect,'receivedAt'=>$a->receivedAt,'id'=>$a->id],$answers));foreach($answers as $a){$v=$scores[$a->userId];$a->points=$v['points'];$a->correctRank=$v['correctRank'];$p=$this->em->find(DuelPlayerRecord::class,['duelId'=>$duelId,'userId'=>$a->userId]);if($p instanceof DuelPlayerRecord)$p->score+=$a->points;}return true;}}
